<script setup>defineProps({ model: { type: Object, required: true } });</script>
<template><article class="panel task-panel"><div class="panel-heading"><div><p class="eyebrow">Task queue</p><h3>Upcoming tasks</h3></div></div><ul class="task-list"><li v-for="task in model.tasks" :key="task.id" class="task-item" :class="{ done: task.done }"><form v-if="model.editingTaskId === task.id" class="task-edit" @submit.prevent="model.saveTaskEdit(task)"><label class="sr-only" :for="`edit-${task.id}`">Edit task</label><input :id="`edit-${task.id}`" v-model="model.editTaskInput" /><button :disabled="!model.editTaskInput.trim()">Save</button><button type="button" @click="model.editingTaskId = null">Cancel</button></form><span v-else>{{ task.text }}</span><div v-if="model.editingTaskId !== task.id" class="task-actions"><button v-if="!task.done" :class="{ selected: model.activeTaskId === task.id }" :aria-pressed="model.activeTaskId === task.id" @click="model.selectTask(task)">{{ model.activeTaskId === task.id ? 'Selected' : 'Focus next' }}</button><button v-if="!task.done" @click="model.beginEditTask(task)">Edit</button><button @click="model.toggleTask(task)">{{ task.done ? 'Undo' : 'Done' }}</button><button class="danger" @click="model.removeTask(task)">Remove</button></div></li></ul><p v-if="model.tasks.length === 0" class="empty-state">Your task list is empty. Add your first focus task above.</p><div v-if="model.removedTask" class="undo-bar" role="status">Task removed. <button @click="model.undoRemoveTask">Undo</button></div></article></template>
